// src/lib/use-current-user.ts
"use client";

import { useEffect, useState } from "react";
import { onAuthStateChanged, User as FirebaseUser } from "firebase/auth";
import { getFirebaseAuth, getFirebaseDb } from "./firebase"; // <- relative import inside /lib
import { doc, getDoc } from "firebase/firestore";
import { User } from "@/types"; // <- you have src/lib/types.ts

export function useCurrentUser() {
  const [user, setUser] = useState<User | null>(null);
  const [firebaseUser, setFirebaseUser] = useState<FirebaseUser | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const auth = getFirebaseAuth();

    const unsubscribe = onAuthStateChanged(auth, async (fbUser) => {
      setFirebaseUser(fbUser);

      if (fbUser) {
        try {
          const db = getFirebaseDb();
          const ref = doc(db, "users", fbUser.uid);
          const snap = await getDoc(ref);

          if (snap.exists()) {
            setUser({ id: snap.id, ...snap.data() } as User);
          } else {
            // fallback if Firestore user doc doesn't exist yet
            const initials =
              fbUser.displayName
                ?.split(" ")
                .map((n) => n[0])
                .join("")
                .toUpperCase() || "U";

            setUser({
              id: fbUser.uid,
              name: fbUser.displayName || "User",
              email: fbUser.email || "",
              avatarInitials: initials,
              tenantId: "", // will be filled after onboarding
            });
          }
        } catch (err) {
          console.error("Error loading user profile:", err);
          setUser(null);
        }
      } else {
        setUser(null);
      }

      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  return { user, firebaseUser, loading };
}
