// src/lib/firebase.ts
import { initializeApp, getApps, getApp, type FirebaseApp } from "firebase/app";
import {
  getAuth,
  initializeAuth,
  browserLocalPersistence,
  inMemoryPersistence,
  type Auth,
} from "firebase/auth";
import { getFirestore, type Firestore } from "firebase/firestore";

// pull from env first
const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY || "",
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN || "",
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID || "",
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET || "",
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID || "",
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID || "",
};

// helper: do we actually have a real project?
const hasValidProject =
  typeof firebaseConfig.projectId === "string" &&
  firebaseConfig.projectId.trim().length > 0;

export function getFirebaseApp(): FirebaseApp {
  if (!getApps().length) {
    return initializeApp(firebaseConfig);
  }
  return getApp();
}

export function getFirebaseAuth(): Auth {
  const app = getFirebaseApp();

  // client
  if (typeof window !== "undefined") {
    try {
      return getAuth(app);
    } catch {
      return initializeAuth(app, {
        persistence: browserLocalPersistence,
      });
    }
  }

  // server
  try {
    return initializeAuth(app, {
      persistence: inMemoryPersistence,
    });
  } catch {
    return getAuth(app);
  }
}

export function getFirebaseDb(): Firestore {
  const app = getFirebaseApp();
  if (!hasValidProject) {
    // don't crash SSR — just tell the caller
    throw new Error(
      "Firestore not available: missing Firebase projectId. Set NEXT_PUBLIC_FIREBASE_PROJECT_ID or hardcode config in src/lib/firebase.ts"
    );
  }
  return getFirestore(app);
}
