"use client";

import React, { useState } from "react";
import { api } from "@/lib/api";
import { useCurrentUser } from "@/lib/use-current-user";

export default function SetupClient() {
  const user = useCurrentUser();
  const [businessName, setBusinessName] = useState("");
  const [businessPhone, setBusinessPhone] = useState("");
  const [loading, setLoading] = useState(false);
  const [done, setDone] = useState(false);

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;
    setLoading(true);
    await api.completeBusinessSetup(user.tenantId, {
      businessName,
      businessPhone,
    });
    setLoading(false);
    setDone(true);
  }

  return (
    <div className="min-h-[70vh] flex items-center justify-center">
      <div className="w-full max-w-lg bg-glass-bg/80 backdrop-blur-xl border border-glass-border rounded-2xl p-8">
        <h1 className="text-2xl font-semibold mb-2">Finish setting up Sylor.ai</h1>
        <p className="text-slate-400 mb-6">
          We’ll connect this account to your business. You can change it later in Settings.
        </p>

        <form onSubmit={handleSubmit} className="space-y-5">
          {/* BUSINESS NAME */}
          <div className="flex flex-col gap-2">
            <label
              htmlFor="businessName"
              className="text-sm font-medium text-slate-200"
            >
              Business name
            </label>
            <input
              id="businessName"
              name="businessName"
              value={businessName}
              onChange={(e) => setBusinessName(e.target.value)}
              required
              placeholder="UrbanLux Construction"
              className="bg-slate-900/40 border border-slate-700 rounded-lg px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-brand-primary"
            />
            <p className="text-xs text-slate-500">
              This will be shown in your SMS conversations.
            </p>
          </div>

          {/* BUSINESS PHONE */}
          <div className="flex flex-col gap-2">
            <label
              htmlFor="businessPhone"
              className="text-sm font-medium text-slate-200"
            >
              Business phone
            </label>
            <input
              id="businessPhone"
              name="businessPhone"
              type="tel"
              value={businessPhone}
              onChange={(e) => setBusinessPhone(e.target.value)}
              required
              placeholder="(747) 555-1234"
              className="bg-slate-900/40 border border-slate-700 rounded-lg px-3 py-2 text-sm outline-none focus:ring-1 focus:ring-brand-primary"
            />
            <p className="text-xs text-slate-500">
              Leads will see this number. Make sure it’s real.
            </p>
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-brand-primary hover:bg-brand-secondary transition-colors rounded-lg py-2.5 font-semibold text-sm"
          >
            {loading ? "Provisioning number..." : "Save & continue"}
          </button>
        </form>

        {done && (
          <p className="mt-4 text-sm text-emerald-400">
            Setup complete. You can go to the dashboard now.
          </p>
        )}
      </div>
    </div>
  );
}
